                if (figure != null && !frozen && !claim.isCorrection()) figure = figure.max(floor);
                if (!frozen) figure = LateCharge.withCharge(claim, figure, today, grace,
                        d -> sheet == null ? zero() : sheet.latePctOn(d), rounding);
